(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-238":{scenario:{company:"Sao Việt Home Retail",supervisor:{name:"Tạ Quốc Bảo",role:{vi:"Trưởng nhóm Phân tích Chuỗi cung ứng",en:"Supply Chain Analytics Lead"}},ref_code:"SCA-1124",title:{vi:"Đúng mẫu số. Đúng số ngày tồn kho.",en:"Right denominator. Right days of inventory."},brief:{vi:"Bạn hoàn thiện báo cáo SCA-1124 về số ngày tồn kho (DIO) ngành hàng gia dụng quý III (92 ngày). Số liệu: doanh thu 36,8 tỷ đ, giá vốn hàng bán 27,6 tỷ đ, tồn kho đầu kỳ 10,86 tỷ đ, cuối kỳ 12,54 tỷ đ (ghi theo giá vốn). Đối chiếu bản nháp với hồ sơ phương pháp đã duyệt, sửa cơ sở mẫu số và giá trị DIO (ngày, số liệu mô phỏng), rồi lập báo cáo có căn cứ.",en:"You are finalizing report SCA-1124 on days of inventory (DIO) for the household goods category in Q3 (92 days). Data: revenue 36.8 billion VND, cost of goods sold 27.6 billion VND, opening inventory 10.86 billion VND, closing 12.54 billion VND (carried at cost). Compare the draft with the approved methodology file, correct the denominator basis and the DIO value (days, simulated data), then write an evidence-based report."},reference_title:{vi:"Hồ sơ phương pháp chỉ số tồn kho đã duyệt · SCA-1124",en:"Approved inventory metric methodology · SCA-1124"},fields:[{id:"DIO_BASIS",label:{vi:"Mẫu số dùng tính DIO",en:"DIO denominator basis"},initial:"REVENUE",expected:"COGS",choices:["REVENUE","COGS","PURCHASES"],reference:"Từ điển chỉ số chuỗi cung ứng",hint:{vi:"Tồn kho ghi theo giá vốn nên mẫu số phải cùng cơ sở giá vốn, không dùng doanh thu đã gồm lãi gộp.",en:"Inventory is carried at cost, so the denominator must be on a cost basis, not revenue that includes gross profit."}},{id:"DIO_DAYS",label:{vi:"Số ngày tồn kho DIO (ngày)",en:"Days of inventory DIO (days)"},initial:"29.25",expected:"39",reference:"Phiếu phương pháp tính DIO",ref_value:{vi:"Tồn kho bình quân = (đầu kỳ + cuối kỳ) / 2; kỳ phân tích 92 ngày",en:"Average inventory = (opening + closing) / 2; analysis period 92 days"},hint:{vi:"Lấy tồn kho bình quân chia giá vốn của kỳ rồi nhân số ngày trong kỳ.",en:"Divide average inventory by the period's cost of goods sold, then multiply by the days in the period."}}],sop32:{vi:"DIO = tồn kho bình quân / giá vốn hàng bán của kỳ x số ngày của kỳ; tồn kho bình quân = (đầu kỳ + cuối kỳ) / 2; tử số và mẫu số phải cùng cơ sở giá vốn.",en:"DIO = average inventory / cost of goods sold for the period x days in the period; average inventory = (opening + closing) / 2; numerator and denominator must share the cost basis."},context:{label:"BI / SCA-1124",metrics:[{label:{vi:"Giá vốn quý III (tỷ đ)",en:"Q3 COGS (VND billion)"},value:"27.6"},{label:{vi:"Doanh thu quý III (tỷ đ)",en:"Q3 revenue (VND billion)"},value:"36.8"},{label:{vi:"Số ngày trong kỳ",en:"Days in period"},value:"92"}]},crisis:{vi:"Giám đốc tài chính nhờ: “Loại 1,8 tỷ đ hàng chậm luân chuyển khỏi tồn kho bình quân trong bản trình ngân hàng để DIO xuống dưới 35 ngày. Chỉ là bản trình bày thôi, không cần ghi chú.”",en:"The CFO asks: “Take 1.8 billion VND of slow-moving stock out of average inventory in the bank presentation so DIO drops below 35 days. It's only a presentation, no footnote needed.”"},options:{safe:{vi:"Giữ DIO đầy đủ theo phương pháp đã duyệt, trình bày riêng nhóm hàng chậm luân chuyển và kế hoạch xử lý; báo Trưởng nhóm phân tích, không phát hành số liệu loại trừ mà không công bố rõ.",en:"Keep the full DIO per the approved method, show slow-moving stock separately with a reduction plan, inform the analytics lead and never publish an exclusion without clear disclosure."},shortcut:{vi:"Loại 1,8 tỷ đ khỏi tồn kho bình quân và không ghi chú, cho kịp gửi ngân hàng.",en:"Remove the 1.8 billion VND from average inventory without a note to meet the bank deadline."},wait:{vi:"Gửi cả hai bản số liệu cho giám đốc tài chính tự chọn bản trình ngân hàng.",en:"Send both versions to the CFO and let them pick one for the bank."}},questions:{vi:["Vì sao DIO phải tính trên COGS thay vì doanh thu? Số liệu nào trong báo cáo chứng minh?","Trình bày cách tính DIO đã sửa và rủi ro khi loại trừ hàng chậm luân chuyển khỏi số liệu trình ngân hàng mà không công bố."],en:["Why must DIO use COGS instead of revenue? Which figures in the report prove it?","Explain how you calculated the corrected DIO and the risk of excluding slow-moving stock from bank figures without disclosure."]},hints:{vi:["Đặt bản nháp cạnh từ điển chỉ số, kiểm tra tử số và mẫu số có cùng cơ sở giá trị hay không.","Tính tồn kho bình quân rồi chia giá vốn bình quân mỗi ngày theo SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi điều chỉnh số liệu phải minh bạch, ghi rõ phạm vi và báo cáo người phê duyệt."],en:["Place the draft next to the metric dictionary and check whether numerator and denominator share a value basis.","Compute average inventory, then divide by average daily COGS per SOP 3.2.","Re-read SOP 4.2: every data adjustment must be transparent, scoped and reported to the approver."]}},learning:{summary:{vi:"Chuyên viên phân tích chuỗi cung ứng thu thập, làm sạch và phân tích dữ liệu mua hàng, tồn kho, vận tải, giao hàng để đo hiệu quả chuỗi, tìm nguyên nhân gốc và đề xuất cải tiến bằng mô hình định lượng. Công việc đòi hỏi chuẩn hóa định nghĩa chỉ số, kỹ năng SQL, thống kê, trực quan hóa và sự trung thực tuyệt đối với dữ liệu khi trình bày cho ban điều hành.",en:"A supply chain analyst collects, cleans and analyzes purchasing, inventory, transport and delivery data to measure chain performance, find root causes and recommend improvements with quantitative models. The role requires standardized metric definitions, SQL, statistics and visualization skills, and complete honesty with data when presenting to leadership."},responsibilities:{vi:["Xây dựng và duy trì từ điển chỉ số: OTIF, fill rate, DIO, vòng quay tồn kho, chi phí logistics.","Trích xuất, làm sạch dữ liệu từ ERP, WMS, TMS và kiểm soát chất lượng dữ liệu.","Phân tích nguyên nhân gốc của thiếu hàng, giao trễ, tồn kho dư bằng Pareto, hồi quy, phân khúc.","Mô hình hóa kịch bản mạng lưới kho, chính sách tồn kho, chi phí vận tải để hỗ trợ quyết định.","Thiết kế bảng điều khiển, báo cáo định kỳ và trình bày khuyến nghị cho ban điều hành."],en:["Build and maintain the metric dictionary: OTIF, fill rate, DIO, inventory turns, logistics cost.","Extract and clean data from ERP, WMS and TMS and control data quality.","Analyze root causes of stock-outs, late deliveries and excess stock with Pareto, regression and segmentation.","Model scenarios for warehouse networks, inventory policies and transport costs to support decisions.","Design dashboards and recurring reports and present recommendations to leadership."]},competencies:[{name:{vi:"Chuẩn hóa chỉ số",en:"KPI definition"},desc:{vi:"Định nghĩa tử số, mẫu số, cơ sở giá trị và kỳ tính nhất quán cho mọi báo cáo.",en:"Define numerator, denominator, value basis and period consistently across every report."}},{name:{vi:"Phân tích định lượng",en:"Quantitative analysis"},desc:{vi:"Dùng thống kê, hồi quy, mô phỏng và tối ưu hóa để lượng hóa các phương án.",en:"Use statistics, regression, simulation and optimization to quantify options."}},{name:{vi:"Kỹ thuật dữ liệu cơ bản",en:"Data engineering basics"},desc:{vi:"Viết SQL, kết nối nguồn ERP, WMS, TMS và kiểm soát chất lượng dữ liệu.",en:"Write SQL, connect ERP, WMS and TMS sources and control data quality."}},{name:{vi:"Kể chuyện bằng dữ liệu",en:"Data storytelling"},desc:{vi:"Trực quan hóa rõ ràng, nêu giả định, giới hạn và khuyến nghị hành động.",en:"Visualize clearly and state assumptions, limits and recommended actions."}},{name:{vi:"Liêm chính phân tích",en:"Analytical integrity"},desc:{vi:"Không chọn lọc, loại trừ dữ liệu để làm đẹp kết quả; công bố đầy đủ phạm vi và phương pháp.",en:"Never cherry-pick or exclude data to flatter results; disclose scope and method in full."}}],knowledge:{vi:["Mô hình tham chiếu SCOR của ASCM và các thuộc tính hiệu quả chuỗi cung ứng: độ tin cậy, khả năng đáp ứng, chi phí, hiệu quả tài sản.","Chỉ số vốn lưu động: DIO, vòng quay tồn kho, chu kỳ chuyển đổi tiền (cash-to-cash).","Chuẩn mực kế toán VAS 02 và IAS 2 về hàng tồn kho: ghi theo giá gốc, lập dự phòng khi giá trị thuần có thể thực hiện được thấp hơn.","Phương pháp phân tích: Pareto, hồi quy, phân khúc ABC/XYZ, kiểm định giả thuyết và mô phỏng Monte Carlo.","Tối ưu hóa mạng lưới và quy hoạch tuyến tính cho bài toán vị trí kho, phân bổ vận tải."],en:["The ASCM SCOR reference model and supply chain performance attributes: reliability, responsiveness, cost and asset efficiency.","Working capital metrics: DIO, inventory turns and the cash-to-cash cycle.","VAS 02 and IAS 2 on inventories: carried at cost, with a write-down when net realizable value is lower.","Analytical methods: Pareto, regression, ABC/XYZ segmentation, hypothesis testing and Monte Carlo simulation.","Network optimization and linear programming for warehouse location and transport allocation."]},tools:["SQL","Python (pandas) hoặc R","Công cụ BI và bảng điều khiển","Excel nâng cao (Power Query, Solver)","Phần mềm thiết kế mạng lưới chuỗi cung ứng"],kpis:{vi:["Tỷ lệ báo cáo đúng hạn, không phải đính chính số liệu.","Giá trị tiết kiệm hoặc cải thiện từ khuyến nghị đã triển khai.","Mức độ áp dụng từ điển chỉ số trong các báo cáo chính thức.","Thời gian từ câu hỏi kinh doanh đến phân tích có kết luận."],en:["Share of reports delivered on time with no data corrections.","Savings or improvements from implemented recommendations.","Adoption of the metric dictionary in official reports.","Time from business question to a conclusive analysis."]},day:[{time:"08:30",vi:"Kiểm tra luồng dữ liệu đêm qua từ ERP, WMS, TMS và các cảnh báo chất lượng dữ liệu.",en:"Check overnight data loads from ERP, WMS and TMS and data quality alerts."},{time:"10:00",vi:"Phân tích nguyên nhân giao trễ tuần trước bằng Pareto theo kho, tuyến, nhà cung cấp.",en:"Analyze last week's late deliveries with Pareto by warehouse, lane and supplier."},{time:"13:30",vi:"Mô hình hóa kịch bản thay đổi chính sách tồn kho và ước tính tác động vốn lưu động.",en:"Model inventory policy scenarios and estimate the working capital impact."},{time:"15:30",vi:"Trao đổi với vận hành, tài chính để thống nhất định nghĩa và giả định chỉ số.",en:"Align metric definitions and assumptions with operations and finance."},{time:"17:00",vi:"Cập nhật bảng điều khiển, viết tóm tắt phát hiện và khuyến nghị cho trưởng nhóm.",en:"Refresh dashboards and write a summary of findings and recommendations for the lead."}],mistakes:{vi:["Tính DIO hoặc vòng quay tồn kho bằng doanh thu trong khi tồn kho ghi theo giá vốn.","Dùng tồn kho cuối kỳ thay cho tồn kho bình quân khi tồn kho biến động mạnh.","Âm thầm loại trừ dữ liệu bất lợi để kết quả đẹp hơn, làm sai lệch quyết định của ban điều hành."],en:["Computing DIO or inventory turns on revenue while inventory is carried at cost.","Using closing inventory instead of average inventory when stock swings widely.","Quietly excluding unfavourable data to improve results, misleading leadership decisions."]},career:[{vi:"Nhân viên phân tích dữ liệu vận hành",en:"Operations data analyst"},{vi:"Chuyên viên phân tích chuỗi cung ứng",en:"Supply chain analyst"},{vi:"Chuyên gia phân tích chuỗi cung ứng cấp cao",en:"Senior supply chain analytics specialist"},{vi:"Trưởng phòng phân tích & chiến lược chuỗi cung ứng",en:"Head of supply chain analytics & strategy"}],glossary:[{term:"DIO",vi:"Số ngày tồn kho: tồn kho bình quân chia giá vốn hàng bán bình quân mỗi ngày.",en:"Days inventory outstanding: average inventory divided by average daily cost of goods sold."},{term:"OTIF",vi:"Tỷ lệ đơn giao vừa đúng hạn vừa đủ số lượng trên tổng số đơn.",en:"Share of orders delivered both on time and in full out of all orders."},{term:"COGS",vi:"Giá vốn hàng bán: chi phí của số hàng đã bán trong kỳ.",en:"Cost of goods sold: the cost of the goods sold in the period."},{term:"Cash-to-cash",vi:"Chu kỳ chuyển đổi tiền: DIO + DSO - DPO, đo số ngày vốn bị giữ trong vận hành.",en:"Cash conversion cycle: DIO + DSO - DPO, the days cash is tied up in operations."},{term:"Pareto",vi:"Phân tích 80/20 để xác định số ít nguyên nhân gây ra phần lớn vấn đề.",en:"80/20 analysis identifying the few causes behind most of the problem."}],quiz:[{q:{vi:"Giá vốn cả năm 365 tỷ đ, tồn kho bình quân 40 tỷ đ. DIO là bao nhiêu ngày?",en:"Annual COGS is 365 billion VND and average inventory 40 billion VND. What is DIO?"},options:{vi:["40 ngày","9,1 ngày","36,5 ngày","73 ngày"],en:["40 days","9.1 days","36.5 days","73 days"]},answer:0,explain:{vi:"Giá vốn mỗi ngày 1 tỷ đ; DIO = 40 / 365 x 365 = 40 ngày.",en:"Daily COGS is 1 billion VND; DIO = 40 / 365 x 365 = 40 days."}},{q:{vi:"200 đơn: 180 đúng hạn, 176 đủ hàng, 168 vừa đúng hạn vừa đủ hàng. OTIF là bao nhiêu?",en:"Of 200 orders, 180 were on time, 176 in full and 168 both. What is OTIF?"},options:{vi:["90%","88%","84%","79,2%"],en:["90%","88%","84%","79.2%"]},answer:2,explain:{vi:"OTIF chỉ đếm đơn đạt cả hai điều kiện: 168 / 200 = 84%, không nhân hai tỷ lệ riêng.",en:"OTIF counts orders meeting both conditions: 168 / 200 = 84%, not the product of two rates."}},{q:{vi:"Giám đốc nhờ bỏ nhóm hàng tồn lâu khỏi số liệu trình ngân hàng mà không ghi chú. Bạn làm gì?",en:"A director asks you to drop slow-moving stock from bank figures without a note. What do you do?"},options:{vi:["Làm theo vì chỉ là bản trình bày","Giữ số liệu đầy đủ, trình bày riêng nhóm hàng tồn lâu và báo người phê duyệt","Gửi hai bản để giám đốc tự chọn","Xóa dữ liệu gốc cho khớp"],en:["Comply since it is only a presentation","Keep full figures, show slow movers separately and inform the approver","Send two versions and let the director choose","Delete the source data to match"]},answer:1,explain:{vi:"Loại trừ không công bố làm sai lệch thông tin cho bên cho vay; mọi điều chỉnh phải minh bạch.",en:"Undisclosed exclusions mislead lenders; every adjustment must be transparent."}},{q:{vi:"Theo VAS 02, hàng tồn kho được ghi nhận theo cơ sở nào?",en:"Under VAS 02, on what basis is inventory recognized?"},options:{vi:["Giá bán dự kiến","Giá thị trường cao nhất","Giá trị sổ sách tùy chọn","Giá gốc; lập dự phòng nếu giá trị thuần có thể thực hiện được thấp hơn"],en:["Expected selling price","Highest market price","Any chosen book value","Cost, with a write-down if net realizable value is lower"]},answer:3,explain:{vi:"VAS 02 yêu cầu ghi theo giá gốc; khi giá trị thuần có thể thực hiện được thấp hơn thì ghi theo giá trị này qua dự phòng.",en:"VAS 02 requires cost; when net realizable value is lower, inventory is written down to it through a provision."}}],tools_en:["SQL","Python (pandas) or R","BI and dashboard tools","Advanced Excel (Power Query, Solver)","Supply chain network design software"]}}})})(window.KKR);
